# Completa la línea marcada y compruébala con py check.
def hallazgos(servicio):
    h = []
    if "@sha256:" not in servicio.get("image", ""):
        h.append("imagen-sin-huella")
    if "user" not in servicio:
        h.append("root")
    # ← añade aquí: cada puerto que no empiece por 127.0.0.1: es «puerto-expuesto»
    return h

print(hallazgos({"image": "ollama/ollama:latest", "ports": ["11434:11434"]}))
